interface Point {
  x: number;
  y: number;
}
interface Size {
  width: number;
  height: number;
}
interface WindowPlacement {
  anchor: Point;
  bounds: Point & Size;
  size: Size;
}

export const getWindowTopLeft = ({
  anchor,
  bounds,
  size,
}: WindowPlacement): Point => {
  const SCREEN_MARGIN = 12;
  const minX = bounds.x + SCREEN_MARGIN;
  const maxX = Math.max(
    minX,
    bounds.x + bounds.width - size.width - SCREEN_MARGIN,
  );
  const maxY = bounds.y + bounds.height - SCREEN_MARGIN;
  const minY = Math.min(maxY, bounds.y + size.height + SCREEN_MARGIN);
  return {
    x: Math.min(maxX, Math.max(minX, anchor.x - size.width / 2)),
    y: Math.min(maxY, Math.max(minY, anchor.y - SCREEN_MARGIN)),
  };
};
